INSERT INTO `pages` VALUES (1,100,0,0,'Главная','<h1>Музыкальная компания полного цикла BOOM</h1>\n<div>Музыкальная компания BooM 9 лет на музыкальном рынке и занимает лидирующие позиции во многих спектрах услуг.<br /> Мы живем музыкой, бесконечно развиваясь в новых музыкальных направлениях.</div>','{\"slides\":[{\"image\":\"slides/1.jpg\",\"video\":\"11LVbxDH_Ec\"},{\"image\":\"slides/2.jpg\",\"video\":\"11LVbxDH_Ec\"},{\"image\":\"slides/3.jpg\",\"video\":\"11LVbxDH_Ec\"},{\"image\":\"slides/4.jpg\",\"video\":\"11LVbxDH_Ec\"}]}','Главная | BOOM','','','2015-03-20 00:00:00',1);
INSERT INTO `pages` VALUES (2,101,0,0,'Контакты','Телефоны, контакты','{\"slides\":[]}','Контакты | BOOM','','','2015-03-20 00:00:00',1);
INSERT INTO `pages` VALUES (3,103,0,0,'О нас','<img src=\"/images/under_construction.jpg\" alt=\"\" width=\"347\" height=\"350\" />','{\"slides\":[]}','О нас | BOOM','','','2015-08-06 22:50:53',1);
INSERT INTO `pages` VALUES (4,104,0,0,'Репетиционные студии','<h1>Репетиционные студии</h1>\n<div>В этой сфере компания BooM без преувеличений самая опытная и продвинутая на музыкальном рынке в Республике Беларусь. Всем желающим предоставляется лучший аппарат от мировых брендов, вместительные комфортные комнаты и доступные цены. Часто проводятся акции на бесплатные репетиции. Предоставляются скидки для постоянных клиентов. Ежедневно у нас репетируют от 20 до 50 музыкальных коллективов и доверяют нам.</div>','{\"slides\":[]}','','','','2015-08-06 22:58:55',1);
INSERT INTO `pages` VALUES (5,105,0,0,'Музыкальная школа','<h1>Музыкальная школа</h1>\n<div>Вы ставите цели, а мы помогаем добиваться их. В нашей школе чувствуешь себя как дома, в окружении талантливых и позитивных педагогов и среди лучшего музыкального оборудования. Каждый выпускник нашей школы получает возможность выступать на большой сцене, а самые талантливые обучатся бесплатно!</div>\n<div>Любой желающий, независимо от возраста и музыкальных предпочтений, может получить консультацию, мастер &ndash; класс, или полноценное образование по любой из музыкальных специальностей. В школе работают признанные действующие музыканты, обладающие колоссальным педагогическим опытом.</div>','{\"slides\":[]}','','','','2015-08-06 22:59:16',1);
INSERT INTO `pages` VALUES (6,106,0,0,'Студия звукозаписи','<h1>Студия звукозаписи</h1>\n<div>EverestMedia это еще одно направление компании BooM, является одной из самых крупнейших студий в Беларуси. Здесь работают лучшие звукорежиссёры, представлены профессиональное оборудование и аппарат на любой вкус. Помимо множества белорусских групп, студию также часто посещают и заграничные гости.</div>','{\"slides\":[]}','','','','2015-08-07 11:04:12',1);
INSERT INTO `pages` VALUES (7,107,0,0,'Прокат музыкального оборудования','<h1>Прокат музыкального оборудования</h1>\n<div>Мы также работаем на фестивалях международного уровня, предоставляя в аренду профессиональное световое и звуковое оборудование. У нас есть все необходимое для праздника любого масштаба: от детского утренника до огромного open-air в 10 000 человек.</div>','{\"slides\":[]}','','','','2015-08-07 11:04:46',1);
INSERT INTO `pages` VALUES (8,108,4,0,'Наша команда','<img src=\"/images/under_construction.jpg\" alt=\"\" width=\"347\" height=\"350\" />','{\"slides\":[]}','','','','2015-08-07 11:11:48',1);
INSERT INTO `pages` VALUES (9,109,4,0,'Цены - Акции','<img src=\\\"/images/studios/akc-1.jpg\\\" alt=\\\"\\\" width=\\\"377\\\" height=\\\"250\\\" /> <img src=\\\"/images/studios/akc-2.jpg\\\" alt=\\\"\\\" width=\\\"444\\\" height=\\\"250\\\" />','{\"slides\":[]}','','','','2015-08-07 11:12:31',1);
INSERT INTO `pages` VALUES (10,110,4,0,'Правила','<h1>Правила посещения студии</h1>\n<div>Запись и отмена репетиций производится&nbsp;<strong>ТОЛЬКО ПО ТЕЛЕФОНУ</strong>, с 11.00 до 23.00 часов ежедневно&nbsp;<br /> <strong>8029 571-41-20(мтс), 8029 636-62-27(вел)</strong>&nbsp;и&nbsp;<strong>8017 327-20-34 (гор)</strong>&nbsp;&nbsp;&nbsp;<br /> <br /> <strong>Сообщения по СМС&nbsp;не рассматриваются!</strong>&nbsp;&nbsp;&nbsp;<br /> <br /> <strong>Отмена репетиции</strong>&nbsp;производится за 48 часов, в противном случае, если нам не удается продать ваше время, вам придется оплатить неустойку 50%. Так же 50% если репетиция отменяется более чем за 24 часа до ее начала. И 100% - если репетиция отменяется менее чем за 24 часа до ее начала. &nbsp;&nbsp;<br /> <br /> Во время репетиции Вы несете материальную ответственность за порчу имущества репетиционной студии.&nbsp;<br /> За оставленные на хранение или забытые вещи администрация ответственности не несет.&nbsp;<br /> Не забывайте возвращать все на свои места и главное - убирать после себя мусор!&nbsp;<br /> <br /> На студиях музыкальной компании \"BOOM\"&nbsp;</div>\n<div><strong>ЗАПРЕЩЕНО</strong>:&nbsp;<br /> - распивать алкогольные напитки и пиво;&nbsp;<br /> - употреблять наркотические вещества;&nbsp;<br /> - приходить на студию в состоянии алкогольного или наркотического опьянения;&nbsp;<br /> - садиться на аппаратуру и оборудование студии;&nbsp;<br /> - самостоятельно менять местоположение музыкального оборудования и инструментов, отсоединять/переподключать силовые и коммутационные кабели:&nbsp;</div>','{\"slides\":[]}','','','','2015-08-07 11:13:11',1);
