INSERT INTO `pages` VALUES (22,122,5,0,'Подарочный сертификат','<img src=\\\"/images/school/certificate.jpg\\\" alt=\\\"\\\" width=\\\"340\\\" height=\\\"500\\\" /> <br /><br /> Больше не нужно мучиться с выбором подарка для друга! Хватит тратить свое время на посещение огромного числа магазинов в поисках чего-то необыкновенного!<br /><br /> Мы предлагаем вам гениальное решение подарить не просто креативный подарок, но новые эмоции и ощущения, которые приятно удивят и запомнятся надолго.<br /><br /> Подарочный сертификат музыкальной школы Boom &ndash; это не просто карта, позволяющая заниматься по любой музыкальной дисциплине с профессиональными преподавателями на хорошем качественном оборудовании, это возможность окунуться в мир музыки, попробовать себя в разных творческих направлениях и, возможно, найти свое призвание и место в жизни. Приобретение новых друзей и веселое времяпрепровождение в сертификат не входит, но гарантируется!<br /><br /> У нас можно приобрести сертификат абсолютно по любой музыкальной дисциплине на любое количество занятий. Сертификат действителен в течение трех месяцев, поэтому одариваемый может сам выбрать время, месяц и даже предмет.<br /><br /> Выходите за рамки ожидаемого, удивляйте, дарите необыкновенные подарки, а мы вам в этом поможем!','{\"slides\":[]}','','','','2015-09-03 12:27:54',1);
