INSERT INTO `pages` VALUES (29,129,6,0,'Контакты','Адрес студии EverestMedia Минск, ул. Октябрьская, 16 (территория завода МЗОР, 4 этаж) Тел для справок: (29) 765-78-79 Адреса в социальных сетях VK: https://vk.com/everestmedia, (администратор - https://vk.com/everest_media) Instagram: https://instagram.com/everestmedia_by/ &laquo;EverestMedia - лучшее место для вашей записи!&raquo;','{\"slides\":[]}','Студия звукозаписи | Контакты','','','2015-11-03 14:04:09',1);
